script:
test("day 31 after January 2026 clamps in February and April and returns in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});

test("day 31 after December 2027 clamps to leap day in February 2028 and returns in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});

test("day 15 is kept every month with no last-day adjustment", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});

test("a count of one returns the single date one month later and keeps day 30", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-04-30", count: 1 }), ["2026-05-30"]);
});

test("day 31 clamps in September and November then returns in October and December", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-08-31", count: 4 }), ["2026-09-30", "2026-10-31", "2026-11-30", "2026-12-31"]);
});

test("the first of the month stays the first across the year boundary", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-01", count: 2 }), ["2027-01-01", "2027-02-01"]);
});

test("day 31 clamps to 28 in non-leap February 2027 and returns in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-31", count: 3 }), ["2027-01-31", "2027-02-28", "2027-03-31"]);
});

test("day 28 is kept on the last day of non-leap February and in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-28", count: 2 }), ["2026-02-28", "2026-03-28"]);
});

test("day 29 clamps to 28 in non-leap February and returns in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-29", count: 2 }), ["2026-02-28", "2026-03-29"]);
});

test("day 27 exists in non-leap February and is kept in both months", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-27", count: 2 }), ["2026-02-27", "2026-03-27"]);
});

test("day 29 exists on leap day in February 2028 and is kept in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-29", count: 2 }), ["2028-02-29", "2028-03-29"]);
});

test("day 30 clamps to 29 in leap February 2028 and returns in March", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-30", count: 2 }), ["2028-02-29", "2028-03-30"]);
});

test("day 28 stays 28 in leap February and is not raised to 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-28", count: 2 }), ["2028-02-28", "2028-03-28"]);
});

test("day 30 is kept as the last day of April and again in May", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-03-30", count: 2 }), ["2026-04-30", "2026-05-30"]);
});

test("day 30 is kept in January and clamps to 28 in non-leap February", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-30", count: 2 }), ["2027-01-30", "2027-02-28"]);
});

test("a leap-day start keeps day 29 until non-leap February then returns to 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-02-29", count: 13 }), ["2028-03-29", "2028-04-29", "2028-05-29", "2028-06-29", "2028-07-29", "2028-08-29", "2028-09-29", "2028-10-29", "2028-11-29", "2028-12-29", "2029-01-29", "2029-02-28", "2029-03-29"]);
});
